body.content:
{% comment %}theme-check-disable UndefinedObject{% endcomment %}
{{ 'section-footer.css' | asset_url | stylesheet_tag }}
{{ 'component-newsletter.css' | asset_url | stylesheet_tag }}
{{ 'component-list-menu.css' | asset_url | stylesheet_tag }}
{{ 'component-list-payment.css' | asset_url | stylesheet_tag }}
{{ 'component-list-social.css' | asset_url | stylesheet_tag }}



<footer class="footer color-{{ section.settings.color_scheme }} gradient section-{{ section.id }}-padding">
  {%- liquid
    assign has_social_icons = true
    assign journal_blog = blogs['news']
    if settings.social_facebook_link == blank and settings.social_instagram_link == blank and settings.social_youtube_link == blank and settings.social_tiktok_link == blank and settings.social_twitter_link == blank and settings.social_pinterest_link == blank and settings.social_snapchat_link == blank and settings.social_tumblr_link == blank and settings.social_vimeo_link == blank
      assign has_social_icons = false
    endif

    if settings.brand_image == blank and settings.brand_headline == blank and settings.brand_description == blank
      assign brand_empty = true
    endif

    if section.blocks.size == 1 and section.blocks[0].type == 'brand_information' and brand_empty and has_social_icons == false and section.settings.newsletter_enable == false and section.settings.enable_follow_on_shop == false
      assign only_empty_brand = true
    endif
  -%}
  {%- if section.blocks.size > 0
    or section.settings.newsletter_enable
    or section.settings.show_social
    and has_social_icons == true
    or section.settings.enable_follow_on_shop
  -%}
    {%- unless only_empty_brand -%}
      <div class="footer__content-top page-width">
        {%- if section.blocks.size > 0 -%}
          {%- liquid
            if section.blocks.size == 9
              assign footer_grid_class = 'grid--3-col-tablet'
            elsif section.blocks.size > 6
              assign footer_grid_class = 'grid--4-col-desktop'
            elsif section.blocks.size > 4
              assign footer_grid_class = 'grid--3-col-tablet'
            endif
          -%}
          <div
            class="footer__blocks-wrapper grid grid--1-col grid--2-col grid--4-col-tablet {{ footer_grid_class }}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
            {% if settings.animations_reveal_on_scroll %}
              data-cascade
            {% endif %}
          >
            {%- for block in section.blocks -%}
              <div
                class="footer-block grid__item{% if block.type == 'link_list' %} footer-block--menu{% endif %}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
                {{ block.shopify_attributes }}
                {% if settings.animations_reveal_on_scroll %}
                  data-cascade
                  style="--animation-order: {{ forloop.index }};"
                {% endif %}
              >
                {%- if block.settings.heading != blank -%}
                  {%- assign footer_block_heading = block.settings.heading | strip -%}
                  {%- assign footer_block_heading_upcase = footer_block_heading | upcase -%}
                  {%- assign footer_block_heading_downcase = footer_block_heading | downcase -%}
                  {%- assign footer_locale = request.locale.iso_code | downcase -%}
                  <h2 class="footer-block__heading inline-richtext">
                    {%- if footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'informacion_empresa' -%}
                      Información de la empresa
                    {%- elsif footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'ayuda_soporte' -%}
                      Ayuda y soporte
                    {%- elsif footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'atención_al_cliente' -%}
                      Atención al cliente
                    {%- elsif footer_locale contains 'es' and footer_block_heading_downcase contains 'encabezados_pie' and footer_block_heading_downcase contains 'atencion_al_cliente' -%}
                      Atención al cliente
                    {%- elsif footer_block_heading contains 't:' -%}
                      {%- assign footer_translated_heading = footer_block_heading | remove_first: 't:' | t -%}
                      {%- if footer_locale contains 'es' and footer_translated_heading == 'Company info' -%}
                        Información de la empresa
                      {%- elsif footer_locale contains 'es' and footer_translated_heading == 'Help & support' -%}
                        Ayuda y soporte
                      {%- elsif footer_locale contains 'es' and footer_translated_heading == 'Customer care' -%}
                        Atención al cliente
                      {%- elsif footer_locale contains 'fr' and footer_translated_heading == 'Company info' -%}
                        Informations sur l'entreprise
                      {%- elsif footer_locale contains 'fr' and footer_translated_heading == 'Help & support' -%}
                        Aide et assistance
                      {%- elsif footer_locale contains 'fr' and footer_translated_heading == 'Customer care' -%}
                        Service client
                      {%- else -%}
                        {{ footer_translated_heading }}
                      {%- endif -%}
                    {%- elsif footer_block_heading_upcase == 'COMPANY INFO' -%}
                      {%- if footer_locale contains 'es' -%}
                        Información de la empresa
                      {%- elsif footer_locale contains 'fr' -%}
                        Informations sur l'entreprise
                      {%- else -%}
                        {{ 'sections.footer_headings.company_info' | t }}
                      {%- endif -%}
                    {%- elsif footer_block_heading_upcase == 'HELP & SUPPORT' -%}
                      {%- if footer_locale contains 'es' -%}
                        Ayuda y soporte
                      {%- elsif footer_locale contains 'fr' -%}
                        Aide et assistance
                      {%- else -%}
                        {{ 'sections.footer_headings.help_support' | t }}
                      {%- endif -%}
                    {%- elsif footer_block_heading_upcase == 'CUSTOMER CARE' -%}
                      {%- if footer_locale contains 'es' -%}
                        Atención al cliente
                      {%- elsif footer_locale contains 'fr' -%}
                        Service client
                      {%- else -%}
                        {{ 'sections.footer_headings.customer_care' | t }}
                      {%- endif -%}
                    {%- else -%}
                      {{- footer_block_heading -}}
                    {%- endif -%}
                  </h2>
                {%- endif -%}

                {%- case block.type -%}
                  {%- when '@app' -%}
                    {% render block %}
                  {%- when 'text' -%}
                    <div class="footer-block__details-content rte">
                      {{ block.settings.subtext }}
                    </div>
                  {%- when 'link_list' -%}
                    {%- if block.settings.menu != blank -%}
                      <ul class="footer-block__details-content list-unstyled">
                        {%- for link in block.settings.menu.links -%}
                          {%- assign footer_link_url = link.url | downcase -%}
                          {%- unless footer_link_url contains '/pages/size-guide' -%}
                            <li>
                              <a
                                href="{{ link.url }}"
                                class="link link--text list-menu__item list-menu__item--link{% if link.active %} list-menu__item--active{% endif %}"
                              >
                                {{ link.title }}
                              </a>
                            </li>
                          {%- endunless -%}
                        {%- endfor -%}
                      </ul>
                    {%- endif -%}
                  {%- when 'brand_information' -%}
                    <div class="footer-block__brand-info">
                      {%- if settings.brand_image != blank -%}
                        {%- assign brand_image_height = settings.brand_image_width
                          | divided_by: settings.brand_image.aspect_ratio
                        -%}
                        <div
                          class="footer-block__image-wrapper"
                          style="max-width: min(100%, {{ settings.brand_image_width }}px);"
                        >
                          {{
                            settings.brand_image
                            | image_url: width: 1100
                            | image_tag:
                              loading: 'lazy',
                              widths: '50, 100, 150, 200, 300, 400, 550, 800, 1100',
                              height: brand_image_height,
                              width: settings.brand_image_width
                          }}
                        </div>
                      {%- endif -%}
                      {%- if settings.brand_headline != blank -%}
                        <h2 class="footer-block__heading rte">{{ settings.brand_headline }}</h2>
                      {%- endif -%}
                      {%- if settings.brand_description != blank -%}
                        <div class="rte">{{ settings.brand_description }}</div>
                      {%- endif -%}
                      {%- if block.settings.show_social and has_social_icons -%}
                        {%- render 'social-icons', class: 'footer__list-social' -%}
                      {%- endif -%}
                    </div>
                  {%- when 'image' -%}
                    <div class="footer-block__details-content footer-block-image {{ block.settings.alignment }}">
                      {%- if block.settings.image != blank -%}
                        {%- assign image_size_2x = block.settings.image_width | times: 2 | at_most: 5760 -%}
                        <div
                          class="footer-block__image-wrapper"
                          style="max-width: min(100%, {{ block.settings.image_width }}px);"
                        >
                          <img
                            srcset="{{ block.settings.image | image_url: width: block.settings.image_width }}, {{ block.settings.image | image_url: width: image_size_2x }} 2x"
                            src="{{ block.settings.image | image_url: width: 760 }}"
                            alt="{{ block.settings.image.alt | escape }}"
                            loading="lazy"
                            width="{{ block.settings.image.width }}"
                            height="{{ block.settings.image.height }}"
                          >
                        </div>
                      {%- else -%}
                        {{ 'image' | placeholder_svg_tag: 'placeholder-svg placeholder' }}
                      {%- endif -%}
                    </div>
                {%- endcase -%}
              </div>
            {%- endfor -%}
          </div>
        {%- endif -%}

        {%- comment -%}
          CRO: removed the footer "Do we ship to my country?" block.
          The same modal is already reachable from the product page via the
          inline "See all current shipping countries" link inside the
          "Shipping & Delivery" panel — surfacing it again sitewide in the
          footer was duplicative and visually heavy.
        {%- endcomment -%}

        {%- if journal_blog != blank and section.settings.show_journal_link -%}
          {%- liquid
            assign footer_journal_label = section.settings.journal_link_label | default: 'Style Journal'
            assign footer_journal_summary = 'Family fashion tips, matching outfit ideas, and seasonal style guides.'
            assign footer_journal_cta_prefix = 'Read the '
            if footer_locale contains 'es'
              assign footer_journal_summary = 'Consejos de moda familiar, ideas de conjuntos a juego y guías de estilo de temporada.'
              assign footer_journal_cta_prefix = 'Leer el '
            endif
          -%}
          <div class="footer-block grid__item footer-block--journal{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
            <h2 class="footer-block__heading inline-richtext">{{ footer_journal_label }}</h2>
            <div class="footer-block__details-content rte">
              <p>{{ footer_journal_summary }}</p>
              <a href="{{ journal_blog.url }}" class="link link--text list-menu__item list-menu__item--link">
                {{ footer_journal_cta_prefix }}{{ footer_journal_label }} &rarr;
              </a>
            </div>
          </div>
        {%- endif -%}

        <div
          class="footer-block--newsletter{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
          {% if settings.animations_reveal_on_scroll %}
            data-cascade
          {% endif %}
        >
          {%- if section.settings.newsletter_enable -%}
            <div class="footer-block__newsletter">
              {%- if section.settings.newsletter_heading != blank -%}
                <h2 class="footer-block__heading inline-richtext">{{ section.settings.newsletter_heading }}</h2>
              {%- endif -%}
              {%- form 'customer', id: 'ContactFooter', class: 'footer__newsletter newsletter-form' -%}
                <input type="hidden" name="contact[tags]" value="newsletter,footer-signup">
                <div class="newsletter-form__field-wrapper">
                  <div class="field">
                    <input
                      id="NewsletterForm--{{ section.id }}"
                      type="email"
                      name="contact[email]"
                      class="field__input"
                      value="{{ form.email }}"
                      aria-required="true"
                      autocorrect="off"
                      autocapitalize="off"
                      autocomplete="email"
                      {% if form.errors %}
                        autofocus
                        aria-invalid="true"
                        aria-describedby="ContactFooter-error"
                      {% elsif form.posted_successfully? %}
                        aria-describedby="ContactFooter-success"
                      {% endif %}
                      placeholder="{{ 'newsletter.label' | t }}"
                      required
                    >
                    <label class="field__label" for="NewsletterForm--{{ section.id }}">
                      {{ 'newsletter.label' | t }}
                    </label>
                    <button
                      type="submit"
                      class="newsletter-form__button field__button"
                      name="commit"
                      id="Subscribe"
                      aria-label="{{ 'newsletter.button_label' | t }}"
                    >
                      {% render 'icon-arrow' %}
                    </button>
                  </div>
                  {%- if form.errors -%}
                    <small
                      class="newsletter-form__message form__message"
                      id="ContactFooter-error"
                      data-analytics-newsletter-state="error"
                    >
                      {%- render 'icon-error' -%}
                      {{- form.errors.translated_fields.email | capitalize }}
                      {{ form.errors.messages.email -}}
                    </small>
                  {%- endif -%}
                </div>
                {%- if form.posted_successfully? -%}
                  <h3
                    class="newsletter-form__message newsletter-form__message--success form__message"
                    id="ContactFooter-success"
                    tabindex="-1"
                    autofocus
                    data-analytics-newsletter-state="success"
                  >
                    {% render 'icon-success' %}
                    {{- 'newsletter.success' | t }}
                  </h3>
                {%- endif -%}
              {%- endform -%}
            </div>
          {%- endif -%}

          {%- if shop.features.follow_on_shop? and section.settings.enable_follow_on_shop -%}
            <div class="footer__follow-on-shop">
              {% comment %} TODO: enable theme-check once `login_button` is accepted as valid filter {% endcomment %}
              {% # theme-check-disable %}
              {{ shop | login_button: action: 'follow' }}
              {% # theme-check-enable %}
            </div>
          {%- endif -%}

          {%- if section.settings.show_social and has_social_icons -%}
            {%- render 'social-icons', class: 'footer__list-social' -%}
          {%- endif -%}
        </div>
      </div>
    {%- endunless -%}
  {%- endif -%}

  <div
    class="footer__content-bottom{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
    {% if settings.animations_reveal_on_scroll %}
      data-cascade
    {% endif %}
  >
    <div class="footer__content-bottom-wrapper page-width">
      <div class="footer__column footer__localization isolate">
        {%- if section.settings.enable_country_selector and localization.available_countries.size > 1 -%}
          <localization-form>
            {%- form 'localization', id: 'FooterCountryForm', class: 'localization-form' -%}
              <div>
                <h2 class="caption-large text-body" id="FooterCountryLabel">{{ 'localization.country_label' | t }}</h2>
                {%- render 'country-localization', localPosition: 'FooterCountry' -%}
              </div>
            {%- endform -%}
          </localization-form>
        {%- endif -%}

        {%- if section.settings.enable_language_selector and localization.available_languages.size > 1 -%}
          <localization-form>
            {%- form 'localization', id: 'FooterLanguageForm', class: 'localization-form' -%}
              <div>
                <h2 class="caption-large text-body" id="FooterLanguageLabel">
                  {{ 'localization.language_label' | t }}
                </h2>
                {%- render 'language-localization', localPosition: 'FooterLanguage' -%}
              </div>
            {%- endform -%}
          </localization-form>
        {%- endif -%}
      </div>
      <div class="footer__column footer__column--info">
        {%- if section.settings.payment_enable -%}
          <div class="footer__payment">
            <span class="visually-hidden">{{ 'sections.footer.payment' | t }}</span>
            <ul class="list list-payment" role="list">
              {%- for type in shop.enabled_payment_types -%}
                <li class="list-payment__item">
                  {{ type | payment_type_svg_tag: class: 'icon icon--full-color' }}
                </li>
              {%- endfor -%}
            </ul>
          </div>
        {%- endif -%}
      </div>
    </div>
    <div class="footer__content-bottom-wrapper page-width{% if section.settings.enable_country_selector == false and section.settings.enable_language_selector == false %} footer__content-bottom-wrapper--center{% endif %}">
      <div class="footer__copyright caption">
        <small class="copyright__content">&copy; {{ 'now' | date: '%Y' }}, {{ shop.name | link_to: routes.root_url -}}</small>
        {%- if section.settings.show_policy -%}
          <ul class="policies list-unstyled">
            {%- for policy in shop.policies -%}
              {%- if policy != blank -%}
                <li>
                  <small class="copyright__content"><a href="{{ policy.url }}">{{ policy.title }}</a></small>
                </li>
              {%- endif -%}
            {%- endfor -%}
            {%- if journal_blog != blank and section.settings.show_journal_link -%}
              <li>
                <small class="copyright__content"><a href="{{ journal_blog.url }}">{{ section.settings.journal_link_label | escape }}</a></small>
              </li>
            {%- endif -%}
          </ul>
        {%- elsif journal_blog != blank and section.settings.show_journal_link -%}
          <small class="copyright__content"><a href="{{ journal_blog.url }}">{{ section.settings.journal_link_label | escape }}</a></small>
        {%- endif -%}
      </div>
    </div>
  </div>
</footer>

{% schema %}
{
  "name": "t:sections.footer.name",
  "blocks": [
    {
      "type": "@app"
    },
    {
      "type": "link_list",
      "name": "t:sections.footer.blocks.link_list.name",
      "settings": [
        {
          "type": "inline_richtext",
          "id": "heading",
          "default": "Quick links",
          "label": "t:sections.footer.blocks.link_list.settings.heading.label"
        },
        {
          "type": "link_list",
          "id": "menu",
          "default": "footer",
          "label": "t:sections.footer.blocks.link_list.settings.menu.label",
          "info": "t:sections.footer.blocks.link_list.settings.menu.info"
        }
      ]
    },
    {
      "type": "brand_information",
      "name": "t:sections.footer.blocks.brand_information.name",
      "settings": [
        {
          "type": "paragraph",
          "content": "t:sections.footer.blocks.brand_information.settings.paragraph.content"
        },
        {
          "type": "header",
          "content": "t:sections.footer.blocks.brand_information.settings.header__1.content"
        },
        {
          "type": "checkbox",
          "id": "show_social",
          "default": true,
          "label": "t:sections.footer.blocks.brand_information.settings.show_social.label",
          "info": "t:sections.footer.blocks.brand_information.settings.show_social.info"
        }
      ]
    },
    {
      "type": "text",
      "name": "t:sections.footer.blocks.text.name",
      "settings": [
        {
          "type": "inline_richtext",
          "id": "heading",
          "default": "Heading",
          "label": "t:sections.footer.blocks.text.settings.heading.label"
        },
        {
          "type": "richtext",
          "id": "subtext",
          "default": "<p>Share contact information, store details, and brand content with your customers.</p>",
          "label": "t:sections.footer.blocks.text.settings.subtext.label"
        }
      ]
    },
    {
      "type": "image",
      "name": "Image",
      "settings": [
        {
          "type": "image_picker",
          "id": "image",
          "label": "Image"
        },
        {
          "type": "range",
          "id": "image_width",
          "min": 50,
          "max": 550,
          "step": 5,
          "unit": "px",
          "label": "Image width",
          "default": 100
        },
        {
          "type": "select",
          "id": "alignment",
          "label": "Image alignment on large screen",
          "options": [
            {
              "value": "",
              "label": "Left"
            },
            {
              "value": "center",
              "label": "Center"
            },
            {
              "value": "right",
              "label": "Right"
            }
          ],
          "default": "center"
        }
      ]
    }
  ],
  "settings": [
    {
      "type": "color_scheme",
      "id": "color_scheme",
      "label": "t:sections.all.colors.label",
      "default": "scheme-1"
    },
    {
      "type": "header",
      "content": "t:sections.footer.settings.header__1.content",
      "info": "t:sections.footer.settings.header__1.info"
    },
    {
      "type": "checkbox",
      "id": "newsletter_enable",
      "default": true,
      "label": "t:sections.footer.settings.newsletter_enable.label"
    },
    {
      "type": "inline_richtext",
      "id": "newsletter_heading",
      "default": "Subscribe to our emails",
      "label": "t:sections.footer.settings.newsletter_heading.label"
    },
    {
      "type": "header",
      "content": "t:sections.footer.settings.header__9.content",
      "info": "t:sections.footer.settings.header__9.info"
    },
    {
      "type": "checkbox",
      "id": "enable_follow_on_shop",
      "default": true,
      "label": "t:sections.footer.settings.enable_follow_on_shop.label"
    },
    {
      "type": "header",
      "content": "t:sections.footer.settings.header__2.content",
      "info": "t:sections.footer.settings.header__2.info"
    },
    {
      "type": "checkbox",
      "id": "show_social",
      "default": true,
      "label": "t:sections.footer.settings.show_social.label"
    },
    {
      "type": "header",
      "content": "t:sections.footer.settings.header__3.content",
      "info": "t:sections.footer.settings.header__4.info"
    },
    {
      "type": "checkbox",
      "id": "enable_country_selector",
      "default": true,
      "label": "t:sections.footer.settings.enable_country_selector.label"
    },
    {
      "type": "header",
      "content": "t:sections.footer.settings.header__5.content",
      "info": "t:sections.footer.settings.header__6.info"
    },
    {
      "type": "checkbox",
      "id": "enable_language_selector",
      "default": true,
      "label": "t:sections.footer.settings.enable_language_selector.label"
    },
    {
      "type": "header",
      "content": "t:sections.footer.settings.header__7.content"
    },
    {
      "type": "checkbox",
      "id": "payment_enable",
      "default": true,
      "label": "t:sections.footer.settings.payment_enable.label"
    },
    {
      "type": "header",
      "content": "t:sections.footer.settings.header__8.content",
      "info": "t:sections.footer.settings.header__8.info"
    },
    {
      "type": "checkbox",
      "id": "show_policy",
      "default": true,
      "label": "t:sections.footer.settings.show_policy.label"
    },
    {
      "type": "checkbox",
      "id": "show_journal_link",
      "default": true,
      "label": "Show Style Journal link"
    },
    {
      "type": "text",
      "id": "journal_link_label",
      "default": "Style Journal",
      "label": "Style Journal footer label"
    },
    {
      "type": "header",
      "content": "t:sections.all.spacing"
    },
    {
      "type": "range",
      "id": "margin_top",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.footer.settings.margin_top.label",
      "default": 0
    },
    {
      "type": "header",
      "content": "t:sections.all.padding.section_padding_heading"
    },
    {
      "type": "range",
      "id": "padding_top",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_top",
      "default": 36
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_bottom",
      "default": 36
    }
  ],
  "default": {
    "blocks": [
      {
        "type": "link_list"
      },
      {
        "type": "text"
      }
    ]
  }
}
{% endschema %}



<script>
window.addEventListener('DOMContentLoaded', () => {
  if (window.matchMedia('(min-width: 750px)').matches) {
    return
  }

  const handleCollapse = (heading) => {
    if (heading.classList.contains('block-collapsed')) {
      heading.classList.remove('block-collapsed')
      heading.setAttribute('aria-expanded', 'true')
      return
    }

    heading.classList.add('block-collapsed')
    heading.setAttribute('aria-expanded', 'false')
  }

  document.querySelectorAll('.footer .footer__blocks-wrapper .footer-block__heading').forEach((heading, index) => {
    const detailsContent = heading.nextElementSibling

    if (!detailsContent) {
      return
    }

    heading.classList.add('block-collapsed')
    heading.setAttribute('role', 'button')
    heading.setAttribute('aria-expanded', 'false')
    heading.setAttribute('tabindex', '0')

    detailsContent.setAttribute('id', `footer-block-index-${index}`)
    heading.setAttribute('aria-controls', `footer-block-index-${index}`)

    heading.addEventListener('click', () => {
      handleCollapse(heading)
    })

    heading.addEventListener('keydown', (event) => {
      // Only handle Enter and Space keys; ignore other key presses
      if (event.key !== 'Enter' && event.key !== ' ') {
        return
      }

      event.preventDefault()
      handleCollapse(heading)
    })
  })
})
</script>

{%- style -%}
  .hero-banner {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: {{ section.settings.height }}px;
    background-color: {{ section.settings.bg_color }};
    overflow: hidden;
  }
  .hero-banner__slides {
    position: absolute;
    inset: 0;
    z-index: 0;
  }
  .hero-banner__slide {
    position: absolute;
    inset: 0;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.6s ease, visibility 0.6s ease;
  }
  .hero-banner__slide.is-active {
    opacity: 1;
    visibility: visible;
  }
  .hero-banner__slide picture {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
  }
  .hero-banner__image {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    /* Force center focal point so subjects (mommy + child) aren't trimmed
       on narrower viewports where the container ratio shifts. */
    object-position: center center;
  }
  .hero-banner__overlay {
    position: absolute;
    inset: 0;
    background: rgba(0,0,0,{{ section.settings.overlay_opacity | divided_by: 100.0 }});
    z-index: 1;
  }
  .hero-banner__surface-link {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: block;
    color: inherit;
    text-decoration: none;
  }
  .hero-banner__surface-link:focus-visible {
    outline: 3px solid rgba(255, 255, 255, 0.95);
    outline-offset: -8px;
  }
  .hero-banner__content {
    position: relative;
    z-index: 4;
    text-align: center;
    padding: 40px 20px;
    max-width: 700px;
    pointer-events: none;
  }
  .hero-banner__heading {
    color: {{ section.settings.text_color }};
    font-size: clamp(28px, 5vw, 48px);
    font-weight: 700;
    line-height: 1.2;
    margin: 0 0 12px;
  }
  .hero-banner__subheading {
    color: {{ section.settings.text_color }};
    font-size: clamp(14px, 2.5vw, 18px);
    margin: 0 0 24px;
    opacity: 0.9;
  }
  .hero-banner__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: center;
    pointer-events: auto;
  }
  .hero-banner__cta {
    position: relative;
    z-index: 4;
    display: inline-block !important;
    align-items: center;
    justify-content: center;
    min-height: 48px;
    color: {{ section.settings.button_text_color }};
    padding: 16px 40px !important;
    font-size: 12px !important;
    font-weight: 700;
    text-decoration: none;
    border-radius: 50px !important;
    transition: transform 0.2s ease, opacity 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
    letter-spacing: 2.5px !important;
    text-transform: uppercase !important;
    white-space: nowrap;
  }
  .hero-banner__cta--primary {
    background: linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%) !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.15) !important;
  }
  .hero-banner__cta--secondary {
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.35);
  }
  .hero-banner__cta:hover {
    transform: translateY(-2px) !important;
    opacity: 0.94;
    box-shadow: 0 8px 25px rgba(232, 93, 58, 0.3) !important;
  }
  .hero-banner__trust {
    display: flex;
    flex-direction: column;
    gap: 12px;
    align-items: center;
    margin-top: 18px;
    pointer-events: auto;
  }
  .hero-banner__trust-line {
    margin: 0;
    color: {{ section.settings.text_color }};
    font-size: 13px;
    font-weight: 600;
    line-height: 1.5;
    opacity: 0.96;
    text-wrap: balance;
  }
  .hero-banner__trust-rating {
    margin: 0;
    color: {{ section.settings.text_color }};
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    opacity: 0.95;
  }
  .hero-banner__trust-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
  }
  .hero-banner__trust-pill {
    position: relative;
    z-index: 4;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 40px;
    padding: 0.7rem 1rem;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.24);
    background: rgba(255, 255, 255, 0.12);
    color: {{ section.settings.text_color }};
    font-size: 13px;
    font-weight: 600;
    line-height: 1.15;
    text-decoration: none;
    backdrop-filter: blur(10px);
  }
  .hero-banner__controls {
    position: absolute;
    right: 20px;
    bottom: 22px;
    left: 20px;
    z-index: 5;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    pointer-events: auto;
  }
  .hero-banner__control,
  .hero-banner__dot {
    border: 0;
    cursor: pointer;
    color: #ffffff;
  }
  .hero-banner__control {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.26);
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.18);
    backdrop-filter: blur(8px);
    transition: background-color 0.2s ease, transform 0.2s ease;
  }
  .hero-banner__control:hover {
    background: rgba(0, 0, 0, 0.38);
    transform: translateY(-1px);
  }
  .hero-banner__control:focus-visible,
  .hero-banner__dot:focus-visible {
    outline: 2px solid rgba(255, 255, 255, 0.96);
    outline-offset: 3px;
  }
  .hero-banner__control .icon {
    width: 14px;
    height: 14px;
  }
  .hero-banner__control--prev .icon {
    transform: rotate(90deg);
  }
  .hero-banner__control--next .icon {
    transform: rotate(-90deg);
  }
  .hero-banner__dots {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 12px;
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(8px);
  }
  .hero-banner__dot {
    width: 9px;
    height: 9px;
    padding: 0;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.62);
    transition: width 0.2s ease, background-color 0.2s ease;
  }
  .hero-banner__dot[aria-current='true'] {
    width: 28px;
    background: {{ section.settings.button_color }};
  }

  /* Desktop: text on left side over empty scenery */
  @media screen and (min-width: 750px) {
    .hero-banner__image {
      /* Keep center focal point on desktop too; the per-slide
         offsets (58%/64% etc.) were trimming subjects on the left edge. */
      object-position: center center;
    }
    .hero-banner__content {
      text-align: left;
      margin-left: 5%;
      margin-right: auto;
    }
    .hero-banner__actions {
      justify-content: flex-start;
    }
    .hero-banner__heading {
      text-shadow: 0 2px 12px rgba(0,0,0,0.5), 0 1px 3px rgba(0,0,0,0.3);
    }
    .hero-banner__subheading {
      text-shadow: 0 1px 8px rgba(0,0,0,0.5), 0 1px 2px rgba(0,0,0,0.3);
    }
  }

  {%- if request.page_type == 'index' and section.index == 1 -%}
    @media screen and (min-width: 750px) {
      #shopify-section-{{ section.id }} .hero-banner {
        min-height: clamp(500px, 42vw, 680px);
      }

      #shopify-section-{{ section.id }} .hero-banner__content {
        max-width: min(46rem, 42%);
      }

      #shopify-section-{{ section.id }} .hero-banner__heading {
        font-size: clamp(32px, 4vw, 48px);
      }

    }

    @media screen and (max-width: 749px) {
      #shopify-section-{{ section.id }} {
        margin-bottom: 7rem;
      }

      #shopify-section-{{ section.id }} .hero-banner {
        min-height: clamp(400px, 108vw, 460px);
        overflow: visible;
      }

      #shopify-section-{{ section.id }} .hero-banner__content {
        position: absolute;
        right: 0;
        bottom: -5.75rem;
        left: 0;
        min-height: 0;
        max-width: none;
        padding: 0 1.6rem;
      }

      #shopify-section-{{ section.id }} .hero-banner__actions {
        width: min(100%, 32rem);
        margin: 0 auto;
        gap: 0.75rem;
        padding: 1rem;
        border-radius: 2rem;
        background: rgba(255, 252, 248, 0.92);
        box-shadow: 0 1rem 2.4rem rgba(42, 29, 14, 0.16);
        backdrop-filter: blur(12px);
      }

      #shopify-section-{{ section.id }} .hero-banner__cta {
        min-height: 44px;
        padding: 0.95rem 1.3rem !important;
        font-size: 11px !important;
        letter-spacing: 0.16em !important;
        line-height: 1.2;
      }

      #shopify-section-{{ section.id }} .hero-banner__cta--secondary {
        background: rgba(255, 255, 255, 0.94) !important;
        color: #1f1f1f !important;
        border: 1px solid rgba(31, 31, 31, 0.12) !important;
        box-shadow: 0 0.5rem 1.2rem rgba(16, 17, 17, 0.08) !important;
        font-size: 10px !important;
        letter-spacing: 0.1em !important;
      }
    }
  {%- endif -%}

  @media screen and (max-width: 749px) {
    .hero-banner__image {
      object-position: var(--hero-slide-mobile-position, 60% 30%);
    }

    .hero-banner__scroll-target-highlight {
      animation: hero-scroll-target-highlight-{{ section.id }} 0.9s ease-out;
    }

    .hero-banner__scroll-target-heading-highlight {
      animation: hero-scroll-target-heading-{{ section.id }} 0.9s ease-out;
    }

    .hero-banner__actions {
      flex-direction: column;
      gap: 8px;
    }

    .hero-banner__cta {
      width: 100%;
      white-space: normal;
    }

    .hero-banner__trust-pills {
      width: 100%;
    }

    .hero-banner__trust-pill {
      flex: 1 1 calc(50% - 10px);
    }

    .hero-banner__heading {
      display: none;
      font-size: 20px;
      line-height: 1.2;
    }

    .hero-banner__subheading {
      display: none;
      font-size: 12px;
    }

    .hero-banner__content {
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      min-height: 100%;
      padding: 42% 20px 24px;
    }

    .hero-banner__controls {
      bottom: 4.6rem;
      gap: 8px;
    }

    .hero-banner__control {
      width: 34px;
      height: 34px;
    }

    .hero-banner__dots {
      gap: 7px;
      padding: 8px 10px;
    }

    {%- if request.page_type == 'index' and section.index == 1 -%}
      #shopify-section-{{ section.id }} .hero-banner__actions {
        flex-direction: row;
        flex-wrap: nowrap;
        gap: 0.5rem;
        padding: 0.85rem;
      }

      #shopify-section-{{ section.id }} .hero-banner__cta {
        flex: 1 1 0;
        width: auto;
        min-width: 0;
        padding: 0.85rem 0.5rem !important;
        font-size: 10px !important;
        letter-spacing: 0.06em !important;
      }

      #shopify-section-{{ section.id }} .hero-banner__trust {
        display: none;
      }
    {%- endif -%}
  }

  @keyframes hero-scroll-target-highlight-{{ section.id }} {
    0% {
      box-shadow: 0 0 0 0 {{ section.settings.button_color | color_modify: 'alpha', 0 }};
      background-color: transparent;
    }
    45% {
      box-shadow: 0 0 0 0.8rem {{ section.settings.button_color | color_modify: 'alpha', 0.22 }};
      background-color: {{ section.settings.button_color | color_modify: 'alpha', 0.1 }};
    }
    100% {
      box-shadow: 0 0 0 0 {{ section.settings.button_color | color_modify: 'alpha', 0 }};
      background-color: transparent;
    }
  }

  @keyframes hero-scroll-target-heading-{{ section.id }} {
    0% {
      transform: translateY(0);
      letter-spacing: normal;
    }
    40% {
      transform: translateY(-2px);
      letter-spacing: 0.08rem;
      color: {{ section.settings.button_color }};
    }
    100% {
      transform: translateY(0);
      letter-spacing: normal;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .hero-banner__slide,
    .hero-banner__control,
    .hero-banner__dot {
      transition: none;
    }
  }

  @media (prefers-reduced-motion: reduce) and (max-width: 749px) {
    .hero-banner__scroll-target-highlight {
      animation: none;
      box-shadow: 0 0 0 0.4rem {{ section.settings.button_color | color_modify: 'alpha', 0.22 }};
    }

    .hero-banner__scroll-target-heading-highlight {
      animation: none;
      color: {{ section.settings.button_color }};
    }
  }
{%- endstyle -%}

{%- liquid
  assign hero_button_link = section.settings.button_link | default: ''
  assign hero_button_scroll_target = blank
  assign hero_button_link_first_char = hero_button_link | slice: 0, 1
  assign hero_secondary_button_link = section.settings.secondary_button_link | default: ''
  assign hero_tertiary_button_link = section.settings.tertiary_button_link | default: ''
  assign hero_heading_tag = 'h2'
  assign hero_image_loading = 'lazy'
  assign hero_image_fetchpriority = 'low'
  assign hero_slide_count = 0

  if request.page_type == 'index' and section.index == 1
    assign hero_heading_tag = 'h1'
  endif

  if section.index == 1
    assign hero_image_loading = 'eager'
    assign hero_image_fetchpriority = 'high'
  endif

  if hero_button_link != blank and hero_button_link_first_char == '#'
    assign hero_button_scroll_target = hero_button_link | remove_first: '#'
  endif

  for block in section.blocks
    if block.type == 'slide'
      assign block_theme_asset = block.settings.theme_asset | strip
      assign block_mobile_theme_asset = block.settings.mobile_theme_asset | strip
      if block.settings.image != blank or block.settings.mobile_image != blank or block_theme_asset != blank or block_mobile_theme_asset != blank
        assign hero_slide_count = hero_slide_count | plus: 1
      endif
    endif
  endfor

  if hero_slide_count == 0
    assign hero_slide_count = 1
  endif
-%}

<div
  class="hero-banner"
  id="HeroBanner-{{ section.id }}"
  role="region"
  aria-roledescription="carousel"
  aria-label="{{ section.settings.heading | default: shop.name | escape }}"
  data-autoplay-interval="{{ section.settings.autoplay_interval | default: 5 | times: 1000 }}"
>
  <div class="hero-banner__slides" id="HeroBannerSlides-{{ section.id }}">
    {%- assign hero_rendered_slide_index = 0 -%}
    {%- for block in section.blocks -%}
      {%- if block.type != 'slide' -%}
        {%- continue -%}
      {%- endif -%}
      {%- liquid
        assign slide_image = block.settings.image
        assign slide_mobile_image = block.settings.mobile_image
        assign slide_theme_asset = block.settings.theme_asset | strip
        assign slide_mobile_theme_asset = block.settings.mobile_theme_asset | strip

        if slide_image == blank and slide_theme_asset == blank and slide_mobile_image == blank and slide_mobile_theme_asset == blank
          continue
        endif

        if slide_image == blank and slide_theme_asset == blank
          assign slide_image = slide_mobile_image
          assign slide_theme_asset = slide_mobile_theme_asset
        endif

        if slide_mobile_image == blank and slide_mobile_theme_asset == blank
          assign slide_mobile_image = slide_image
          assign slide_mobile_theme_asset = slide_theme_asset
        endif

        assign slide_desktop_position = block.settings.desktop_object_position | strip
        assign slide_mobile_position = block.settings.mobile_object_position | strip
        if slide_desktop_position == blank
          assign slide_desktop_position = 'center center'
        endif
        if slide_mobile_position == blank
          assign slide_mobile_position = slide_desktop_position
        endif

        assign hero_rendered_slide_index = hero_rendered_slide_index | plus: 1
        assign slide_loading = 'lazy'
        assign slide_fetchpriority = 'low'
        if section.index == 1 and hero_rendered_slide_index == 1
          assign slide_loading = hero_image_loading
          assign slide_fetchpriority = hero_image_fetchpriority
        endif

        assign slide_alt = block.settings.image_alt | default: slide_image.alt | default: slide_mobile_image.alt | default: section.settings.heading | default: shop.name | strip
        assign slide_img_width = 2400
        assign slide_img_height = 1200
        if slide_mobile_image != blank
          assign slide_img_width = slide_mobile_image.width
          assign slide_img_height = slide_mobile_image.height
        elsif slide_mobile_theme_asset != blank and slide_mobile_theme_asset != slide_theme_asset
          assign slide_img_width = 1200
          assign slide_img_height = 1600
        endif
      -%}
      <div
        class="hero-banner__slide{% if hero_rendered_slide_index == 1 %} is-active{% endif %}"
        id="HeroBannerSlide-{{ section.id }}-{{ hero_rendered_slide_index }}"
        role="group"
        aria-roledescription="slide"
        aria-label="Hero image {{ hero_rendered_slide_index }} of {{ hero_slide_count }}"
        aria-hidden="{% if hero_rendered_slide_index == 1 %}false{% else %}true{% endif %}"
        data-hero-slide
        style="--hero-slide-desktop-position: {{ slide_desktop_position | escape }}; --hero-slide-mobile-position: {{ slide_mobile_position | escape }};"
        {{ block.shopify_attributes }}
      >
        <picture>
          {%- if slide_image != blank -%}
            <source
              media="(min-width: 750px)"
              srcset="{{ slide_image | image_url: width: 750 }} 750w, {{ slide_image | image_url: width: 1100 }} 1100w, {{ slide_image | image_url: width: 1500 }} 1500w, {{ slide_image | image_url: width: 2000 }} 2000w, {{ slide_image | image_url: width: 2400 }} 2400w"
              sizes="100vw"
            >
          {%- elsif slide_theme_asset != blank -%}
            <source
              media="(min-width: 750px)"
              srcset="{{ slide_theme_asset | asset_url }}"
            >
          {%- endif -%}

          {%- if slide_mobile_image != blank -%}
            <img
              class="hero-banner__image"
              src="{{ slide_mobile_image | image_url: width: 1200 }}"
              alt="{{ slide_alt | escape }}"
              loading="{{ slide_loading }}"
              fetchpriority="{{ slide_fetchpriority }}"
              decoding="async"
              width="{{ slide_img_width }}"
              height="{{ slide_img_height }}"
            >
          {%- elsif slide_mobile_theme_asset != blank -%}
            <img
              class="hero-banner__image"
              src="{{ slide_mobile_theme_asset | asset_url }}"
              alt="{{ slide_alt | escape }}"
              loading="{{ slide_loading }}"
              fetchpriority="{{ slide_fetchpriority }}"
              decoding="async"
              width="{{ slide_img_width }}"
              height="{{ slide_img_height }}"
            >
          {%- endif -%}
        </picture>
      </div>
    {%- endfor -%}

    {%- if hero_rendered_slide_index == 0 -%}
      <div
        class="hero-banner__slide is-active"
        id="HeroBannerSlide-{{ section.id }}-1"
        role="group"
        aria-roledescription="slide"
        aria-label="Hero image 1 of 1"
        aria-hidden="false"
        data-hero-slide
        style="--hero-slide-desktop-position: center center; --hero-slide-mobile-position: 60% 30%;"
      >
        {%- if section.settings.image != blank -%}
          {%- liquid
            assign hero_image_alt = section.settings.image.alt | default: section.settings.heading | default: shop.name
            assign hero_image_width = section.settings.image.width | at_most: 2000
          -%}
          {{
            section.settings.image
            | image_url: width: hero_image_width
            | image_tag:
              class: 'hero-banner__image',
              widths: '480, 640, 750, 960, 1200, 1500, 1800, 2000',
              sizes: '100vw',
              alt: hero_image_alt,
              loading: hero_image_loading,
              fetchpriority: hero_image_fetchpriority,
              decoding: 'async'
          }}
        {%- else -%}
          {{ 'hero-apparel-1' | placeholder_svg_tag: 'placeholder-svg hero-banner__image' }}
        {%- endif -%}
      </div>
    {%- endif -%}
  </div>
  <div class="hero-banner__overlay"></div>
  {%- if hero_button_link != blank and hero_button_link_first_char != '#' -%}
    <a
      href="{{ hero_button_link }}"
      class="hero-banner__surface-link"
      aria-label="{{ section.settings.button_label | default: section.settings.heading | escape }}"
    ></a>
  {%- endif -%}
  <div class="hero-banner__content">
    {%- if section.settings.heading != blank -%}
      <{{ hero_heading_tag }} class="hero-banner__heading">{{ section.settings.heading }}</{{ hero_heading_tag }}>
    {%- endif -%}
    {%- if section.settings.subheading != blank -%}
      <p class="hero-banner__subheading">{{ section.settings.subheading }}</p>
    {%- endif -%}
    <div class="hero-banner__actions">
      {%- if section.settings.button_label != blank -%}
        <a
          href="{{ hero_button_link }}"
          class="hero-banner__cta hero-banner__cta--primary"
          id="HeroBannerCta-{{ section.id }}"
          {% if hero_button_scroll_target != blank %}
            data-scroll-target="{{ hero_button_scroll_target }}"
          {% endif %}
        >
          {{ section.settings.button_label }}
        </a>
      {%- endif -%}
      {%- if section.settings.secondary_button_label != blank and hero_secondary_button_link != blank -%}
        <a
          href="{{ hero_secondary_button_link }}"
          class="hero-banner__cta hero-banner__cta--secondary"
        >
          {{ section.settings.secondary_button_label }}
        </a>
      {%- endif -%}
      {%- if section.settings.tertiary_button_label != blank and hero_tertiary_button_link != blank -%}
        <a
          href="{{ hero_tertiary_button_link }}"
          class="hero-banner__cta hero-banner__cta--secondary"
        >
          {{ section.settings.tertiary_button_label }}
        </a>
      {%- endif -%}
    </div>
    {%- if section.settings.show_trust -%}
      <div class="hero-banner__trust"{% if section.settings.trust_line != blank %} aria-label="{{ section.settings.trust_line | escape }}"{% else %} aria-label="{{ 'sections.cart.trust.secure_checkout' | t | escape }}"{% endif %}>
        {%- if section.settings.trust_line != blank -%}
